def build_prompt():
    return (
        "Translate the following sentence into Spanish.\n\n"
        "Sentence: The train leaves at nine in the morning."
    )

def build_prompt(source_text, target_language):
    return (
        f"Translate the following sentence into {target_language}.\n\n"
        f"Sentence: {source_text}"
    )

build_prompt("The train leaves at nine in the morning.", "Spanish")
build_prompt("Please confirm the delivery address.", "Japanese")

{
  "name": "translate-text",
  "description": "Translate a piece of text into a target language",
  "arguments": [
    { "name": "source_text", "description": "The text to translate", "required": true },
    { "name": "target_language", "description": "The language to translate into", "required": true }
  ]
}

def draft_refund_reply():
    return "Write a polite reply approving a refund for order 10432."

def draft_shipping_reply():
    return "Write a polite reply explaining a shipping delay for order 10891."

def draft_reply(order_id, issue_type, tone="polite"):
    return (
        f"Write a {tone} reply addressing a {issue_type} issue "
        f"for order {order_id}."
    )

draft_reply("10432", "refund approval")
draft_reply("10891", "shipping delay")
